export function getDetailedLessonContent(lessonId, subjectCode, topicReference) {
  if (lessonId && lessonContentMap[lessonId]) {
    return lessonContentMap[lessonId];
  }

  // Fallback lookup by matching topic reference or code
  const entries = Object.values(lessonContentMap);
  if (topicReference) {
    const cleanRef = String(topicReference).trim().toLowerCase();
    const match = entries.find(l => l.officialTopicReference.toLowerCase() === cleanRef || l.title.toLowerCase() === cleanRef);
    if (match) return match;
  }

  if (subjectCode) {
    const match = entries.find(l => l.subjectCode === subjectCode);
    if (match) return match;
  }

  return entries[0] || null;
}
